const yearSpan=document.getElementById("year"),currentYear=(new Date).getFullYear();yearSpan.textContent=currentYear,console.log("Website loaded successfully! Current year is: "+currentYear);const contactForm=document.getElementById("contact-form");contactForm.addEventListener("submit",(function(e){e.preventDefault();const t=document.getElementById("name").value.trim(),n=document.getElementById("email").value.trim(),a=document.getElementById("message").value.trim();""===t||""===n||""===a?alert("Please fill out all fields before submitting."):(alert("Thank you for your message! I will get back to you soon."),contactForm.reset())}));